import React, { useEffect, useState } from "react";
import axios from "../utils/axios";
import { useNavigate } from "react-router-dom";
import CreateBudgetForm from "../components/CreateBudgetForm";

const MONTHS = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];

const BudgetCard = ({ budget, onClick }) => {
  const now = new Date();
  const spent = (budget.expenses || []).filter(e => {
    const d = new Date(e.date);
    return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear();
  }).reduce((s, e) => s + (e.amount || 0), 0);
  const pct = budget.amount > 0 ? Math.min((spent / budget.amount) * 100, 100) : 0;
  const over = spent > budget.amount;

  return (
    <div onClick={onClick} style={styles.budgetCard} onMouseEnter={e => e.currentTarget.style.borderColor = "#bfdbfe"} onMouseLeave={e => e.currentTarget.style.borderColor = "#e8e8e6"}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 12 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <div style={styles.icon}>{budget.icon || "💰"}</div>
          <div>
            <div style={{ fontSize: 15, fontWeight: 600, color: "#191919" }}>{budget.name}</div>
            <div style={{ fontSize: 12, color: "#9b9b9b", marginTop: 2 }}>{(budget.expenses || []).length} transactions</div>
          </div>
        </div>
        <div style={{ textAlign: "right" }}>
          <div style={{ fontSize: 13, fontWeight: 600, color: over ? "#dc2626" : "#191919" }}>RM {spent.toFixed(0)}</div>
          <div style={{ fontSize: 11, color: "#9b9b9b" }}>of RM {(budget.amount || 0).toFixed(0)}</div>
        </div>
      </div>
      <div style={{ height: 4, background: "#f1f1ef", borderRadius: 2, overflow: "hidden" }}>
        <div style={{ height: "100%", width: `${pct}%`, background: over ? "#dc2626" : pct > 80 ? "#d97706" : "#2563eb", borderRadius: 2, transition: "width 0.4s ease" }} />
      </div>
      <div style={{ fontSize: 11, color: "#9b9b9b", marginTop: 8 }}>{pct.toFixed(0)}% used</div>
    </div>
  );
};

const Budgets = () => {
  const [budgets, setBudgets] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const navigate = useNavigate();

  const fetch = async () => {
    try {
      const email = localStorage.getItem("email");
      const r = await axios.get("/api/budgets", { headers: { email } });
      setBudgets(Array.isArray(r.data) ? r.data : []);
    } catch (e) { console.error(e); }
  };

  useEffect(() => { fetch(); }, []);

  return (
    <div style={{ fontFamily: "'Inter', sans-serif" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: 32 }}>
        <div>
          <div style={{ fontSize: 11, color: "#9b9b9b", letterSpacing: "0.06em", textTransform: "uppercase", marginBottom: 6 }}>Finance</div>
          <h1 style={styles.pageTitle}>Budgets</h1>
          <p style={{ fontSize: 14, color: "#6b6b6b", marginTop: 6 }}>Manage your spending categories</p>
        </div>
        <button onClick={() => setShowForm(true)} style={styles.createBtn} onMouseEnter={e => e.currentTarget.style.background = "#1d4ed8"} onMouseLeave={e => e.currentTarget.style.background = "#2563eb"}>
          + New Budget
        </button>
      </div>

      {budgets.length === 0 ? (
        <div style={styles.empty}>
          <div style={{ fontSize: 32, marginBottom: 12 }}>◉</div>
          <div style={{ fontSize: 16, fontWeight: 600, color: "#374151", marginBottom: 8 }}>No budgets yet</div>
          <div style={{ fontSize: 14, color: "#9b9b9b", marginBottom: 20 }}>Create your first budget to start tracking expenses</div>
          <button onClick={() => setShowForm(true)} style={styles.createBtn}>Create Budget</button>
        </div>
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))", gap: 16 }}>
          {budgets.map(b => (
            <BudgetCard key={b.id} budget={b} onClick={() => navigate(`/budgets/${b.id}/expenses`)} />
          ))}
        </div>
      )}

      {showForm && (
        <div style={styles.overlay} onClick={() => setShowForm(false)}>
          <div style={styles.modal} onClick={e => e.stopPropagation()}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 24 }}>
              <h2 style={{ margin: 0, fontSize: 18, fontWeight: 600, color: "#191919" }}>New Budget</h2>
              <button onClick={() => setShowForm(false)} style={styles.closeBtn}>✕</button>
            </div>
            <CreateBudgetForm onSuccess={() => { setShowForm(false); fetch(); }} />
          </div>
        </div>
      )}
    </div>
  );
};

const styles = {
  pageTitle: { fontSize: 28, fontWeight: 700, color: "#191919", margin: 0, letterSpacing: "-0.03em" },
  createBtn: { padding: "9px 18px", background: "#2563eb", color: "#fff", border: "none", borderRadius: 8, fontSize: 14, fontWeight: 500, cursor: "pointer", fontFamily: "'Inter', sans-serif", transition: "background 0.15s" },
  budgetCard: { padding: 20, background: "#fff", border: "1px solid #e8e8e6", borderRadius: 10, cursor: "pointer", transition: "border-color 0.15s" },
  icon: { width: 36, height: 36, borderRadius: 8, background: "#eff6ff", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18 },
  empty: { textAlign: "center", padding: "80px 0", color: "#9b9b9b" },
  overlay: { position: "fixed", inset: 0, background: "rgba(0,0,0,0.3)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 100, backdropFilter: "blur(2px)" },
  modal: { background: "#fff", borderRadius: 12, padding: "28px", width: "100%", maxWidth: 420, boxShadow: "0 20px 60px rgba(0,0,0,0.15)" },
  closeBtn: { background: "none", border: "none", fontSize: 16, color: "#9b9b9b", cursor: "pointer", padding: "4px 8px", borderRadius: 4 },
};

export default Budgets;
